    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "env": [
              {
                "name": "CONFIG_MESSAGE",
                "valueFrom": {
                  "configMapKeyRef": {
                    "name": "app-config",
                    "key": "message"
                  }
                }
              }
            ]
          }
        ]
      }
    }
  }
}
```
